Proceso SumaDeRango
    Definir inicio Como Entero;
    Definir fin Como Entero;
    Definir i Como Entero;
    Definir total Como Entero;
    Leer inicio;
    Leer fin;
    total <- 0;
    Para i <- inicio Hasta fin Hacer
        total <- total + i;
    FinPara
    Escribir total;
FinProceso
